// Every image that content files can use, by key. Generated by the pipelines:
// photos.ts (client photos, `vp run images`) and mock.ts (MOCK photos, `vp run mockups`).
// Content files store the key; components look up src, size, and blur preview here.

import { mockImages } from './mock.ts'
import { photos } from './photos.ts'
import type { ImageAsset } from './types.ts'

export const images = { ...photos, ...mockImages } satisfies Record<string, ImageAsset>

export type ImageKey = keyof typeof images
export type { ImageAsset }

/** Key of a mock image (public/mock/): content that uses one must be `mock: true`. */
export function isMockImage(key: ImageKey): boolean {
  return key in mockImages
}
